parameters.jsCode:
const items = $input.all();
const competitors = $('Notion Get Competitors').all();
const changes = [];

for (let i = 0; i < items.length; i++) {
  const html = items[i].json.data || items[i].json.body || '';
  const comp = competitors[i];
  if (!comp) continue;

  const props = comp.json.properties || {};
  const name = props['Name']?.title?.map(t => t.plain_text).join('') || 'Unknown';
  const prevDescription = props['Description']?.rich_text?.map(t => t.plain_text).join('') || '';
  const prevPricing = props['Pricing']?.rich_text?.map(t => t.plain_text).join('') || '';

  // Extract title
  const titleMatch = html.match(/<title[^>]*>([^<]+)<\/title>/i);
  const currentTitle = titleMatch ? titleMatch[1].trim() : '';

  // Extract meta description
  const descMatch = html.match(/<meta[^>]*name=["']description["'][^>]*content=["']([^"']+)["']/i);
  const currentDescription = descMatch ? descMatch[1].trim() : '';

  // Detect pricing keywords
  const pricingMatch = html.match(/\$[\d,]+(\.\d{2})?\/?\s*(mo|month|year|yr)/gi);
  const currentPricing = pricingMatch ? pricingMatch.slice(0, 5).join(', ') : '';

  const changed = [];
  if (currentDescription && currentDescription !== prevDescription) changed.push('description');
  if (currentPricing && currentPricing !== prevPricing) changed.push('pricing');

  changes.push({
    json: {
      pageId: comp.json.id,
      name,
      currentTitle,
      currentDescription: currentDescription.substring(0, 500),
      currentPricing,
      prevDescription,
      prevPricing,
      hasChanges: changed.length > 0,
      changedFields: changed.join(', '),
      scrapedAt: new Date().toISOString()
    }
  });
}

return changes;

const items = $input.all();
const allItems = $('Extract and Compare').all();
const changedItems = allItems.filter(i => i.json.hasChanges);

if (changedItems.length === 0) {
  return [{ json: { hasChanges: false, report: 'No changes detected this week.' } }];
}

const report = changedItems.map(item => {
  const d = item.json;
  let diff = `## ${d.name}\nChanged: ${d.changedFields}\n`;
  if (d.changedFields.includes('description')) {
    diff += `\nDescription:\n  Before: ${d.prevDescription.substring(0, 200)}\n  After: ${d.currentDescription.substring(0, 200)}\n`;
  }
  if (d.changedFields.includes('pricing')) {
    diff += `\nPricing:\n  Before: ${d.prevPricing}\n  After: ${d.currentPricing}\n`;
  }
  return diff;
}).join('\n---\n');

return [{
  json: {
    hasChanges: true,
    changedCount: changedItems.length,
    totalScraped: allItems.length,
    report
  }
}];

